export function createEntrypointPackageLayout(entrypoint, cwd = "/work", pathValue = "/usr/bin:/bin") {
  if (!entrypoint) throw new Error("missing entrypoint");
  const candidates =
    !entrypoint.includes("/") && !entrypoint.includes("\\")
      ? pathValue
          ?.split(":")
          .map((directory) => `${cwd}/${directory}/${entrypoint}`)
      : undefined;
  const selected = candidates?.find((candidate) => candidate.includes("/bin/"));
  return { packageDir: selected ?? `${cwd}/${entrypoint}`, candidates: candidates ?? [] };
}
